<script setup>
import { computed, onMounted, ref } from 'vue'
import { t } from '../i18n'

const props = defineProps({ main: { type: Array, default: () => [] }, sub: { type: Array, default: () => [] }, visitor: Boolean })
const emit = defineEmits(['add', 'remove'])
const visible = ref(false); const items = ref([]); const message = ref('')
const commonItems = computed(() => items.value.filter(item => item.common))
const installedItems = computed(() => items.value.filter(item => !item.common))
const mainItems = computed(() => installedItems.value.filter(item => item.placement === 'main'))
const subItems = computed(() => installedItems.value.filter(item => item.placement === 'sub'))
async function load() { try { const reply = await fetch('http://127.0.0.1:8003/api/indicators/', { credentials: 'include' }); const data = await reply.json(); if (reply.ok) items.value = data.items; else message.value = data.error || '指标库暂不可用。' } catch { message.value = '指标库暂不可用。' } }
function selected(item) { return (item.placement === 'main' ? props.main : props.sub).some(current => current.code === item.code) }
function blocked(item) { return props.visitor && !item.visitor_available }
function toggle(item) { if (blocked(item)) { message.value = '访客模式仅可启用 MA、BOLL、VOL、MACD、KDJ、RSI；已安装公式仅供预览。'; return }; if (selected(item)) return emit('remove', item); if (item.placement === 'sub' && props.sub.length >= 3) { message.value = '副图最多同时展示 3 个指标，请先移除一个。'; return } message.value = ''; emit('add', item) }
defineExpose({ open: () => { visible.value = true; load() } }); onMounted(load)
</script>
<template>
  <div v-if="visible" class="drawer-mask" @click.self="visible=false"><aside class="drawer"><header><div><small>INDICATORS</small><b>{{ t('indicators') }}</b><span>{{ visitor ? `${t('visitor')} · ${t('guestAvailable')}` : t('installed') }}</span></div><button @click="visible=false">×</button></header><p v-if="message" class="message">{{message}}</p><div class="drawer-body"><section><h3>{{ t('common') }} <em>{{ t('guestAvailable') }}</em></h3><div class="quick-grid"><button v-for="item in commonItems" :key="item.code" :class="{selected:selected(item)}" @click="toggle(item)"><b>{{item.code}}</b><small>{{item.name}}</small><span>{{selected(item)?t('remove'):t('add')}}</span></button></div></section><section><h3>{{ t('installedMain') }}</h3><button v-for="item in mainItems" :key="item.code" class="formula-item" :class="{locked:blocked(item),selected:selected(item)}" @click="toggle(item)"><span><b>{{item.name}}</b><small>{{item.code}} · {{ t('privateFormula') }}</small></span><em>{{blocked(item)?t('member'):selected(item)?t('remove'):t('add')}}</em></button><p v-if="!mainItems.length" class="empty">{{ t('noMain') }}</p></section><section><h3>{{ t('installedSub') }} <em>{{sub.length}} / 3</em></h3><button v-for="item in subItems" :key="item.code" class="formula-item" :class="{locked:blocked(item),selected:selected(item)}" @click="toggle(item)"><span><b>{{item.name}}</b><small>{{item.code}} · {{ t('privateFormula') }}</small></span><em>{{blocked(item)?t('member'):selected(item)?t('remove'):t('add')}}</em></button><p v-if="!subItems.length" class="empty">{{ t('noSub') }}</p></section></div><footer>{{ t('protected') }}</footer></aside></div>
</template>
<style scoped>
.drawer-mask{position:fixed;inset:0;z-index:20;background:#02060b80;display:flex;justify-content:flex-end}.drawer{width:min(410px,94vw);height:100%;background:#101925;border-left:1px solid #385065;box-shadow:-18px 0 50px #0008;display:flex;flex-direction:column}.drawer header{height:auto;display:flex;justify-content:space-between;align-items:flex-start;padding:20px;border-bottom:1px solid #29394c}.drawer header small,.drawer header span{display:block;color:#8299aa;font:10px 'DM Mono',monospace;letter-spacing:.08em}.drawer header b{display:block;margin:4px 0;color:#edf5fa;font-size:20px}.drawer header button{border:0;background:transparent;color:#bed0dd;font-size:28px;line-height:1}.drawer-body{overflow:auto;padding:15px 17px 24px}.drawer h3{display:flex;align-items:center;justify-content:space-between;margin:14px 0 9px;color:#d9e6ed;font-size:13px}.drawer h3 em{color:#78d5b7;font-size:10px;font-style:normal;font-weight:400}.quick-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.quick-grid button,.formula-item{border:1px solid #304357;border-radius:5px;background:#0b141e;color:#dce9f0;text-align:left}.quick-grid button{min-height:69px;padding:9px}.quick-grid b,.quick-grid small,.quick-grid span{display:block}.quick-grid b{color:#67d7b5;font:13px 'DM Mono'}.quick-grid small{margin-top:2px;color:#a7b8c4;font-size:10px}.quick-grid span{margin-top:6px;color:#6e9bbc;font-size:10px}.quick-grid button.selected,.formula-item.selected{border-color:#3ca986;background:#102d31}.formula-item{width:100%;display:flex;justify-content:space-between;align-items:center;padding:10px;margin:6px 0}.formula-item b,.formula-item small{display:block}.formula-item b{font-size:12px}.formula-item small{margin-top:3px;color:#7e95a8;font-size:10px}.formula-item em{color:#72b8f4;font-size:10px;font-style:normal}.formula-item.locked{opacity:.58}.formula-item.locked em{color:#e2ad57}.empty,.message{font-size:11px;color:#8096a8}.message{padding:0 17px;color:#f5c75b}footer{margin-top:auto;padding:13px 17px;border-top:1px solid #29394c;color:#738b9f;font-size:10px}
</style>
